def mean_absolute_deviation(numbers: List[float]) -> float:
    if not numbers:
        raise ValueError("List must not be empty")

    n = len(numbers)
    mean = sum(numbers) / n
    mad = sum(abs(x - mean) for x in numbers) / n
    return float(mad)
