def cantor_numbering(N: int) -> str:
    if N < 1 or not isinstance(N, int):
        return "Invalid input"

    d = 1
    while N > d:
        N -= d
        d += 1

    numerator = N
    denominator = d - N + 1

    if d % 2 == 0:
        numerator, denominator = denominator, numerator

    return f"{numerator}/{denominator}"

