@functools.lru_cache
def dp(steps, pos):
    if steps == 0:
        return 1
    return dp(steps - 1, (pos + 1) % n) + dp(steps - 1, (pos - 1) % n)

count_passing_ways = lambda n, m: dp(m, 0)

def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        return 0
    if m == 0:
        return 1
    if n == 1:
        return 0 if m > 0 else 1
    if n == 2:
        if m % 2 == 0:
            return 1
        else:
            return 0
    if n >= 3:
        prev = [0] * n
        prev[0] = 1
        for _ in range(1, m + 1):
            curr = [0] * n
            for i in range(n):
                left = (i - 1) % n
                right = (i + 1) % n
                curr[i] = prev[left] + prev[right]
            prev = curr
        return prev[0]

def count_passing_ways(n: int, m: int) -> int:
    if n < 1 or m < 1:
        return 0
    if n == 1:
        return 1
    if n == 2:
        return 1 if m % 2 == 0 else 0

    dp = [1] + [0] * (n - 1)

    for _ in range(m):
        prev = [0] * n
        for i in range(n):
            prev[i] = dp[i]
        dp = [0] * n
        dp[(0 + 1) % n] += prev[n - 1] + prev[0]
        dp[0] += prev[1]
        for i in range(1, n - 1):
            dp[i] = prev[i - 1] + prev[i + 1]
        dp[n - 1] += prev[n - 2] + prev[0]

    return dp[0]

