def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize a 1D DP array of size n+1, where dp[j] represents the max importance with budget j
    dp = [0] * (n + 1)

    for i in range(m):
        price = items[i][0]
        value = items[i][1]
        # Traverse from n down to price to avoid reusing the same item
        for j in range(n, price - 1, -1):
            if dp[j - price] + value > dp[j]:
                dp[j] = dp[j - price] + value

    return dp[n]

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    if n < 0:
        n = 0
    if m < 0:
        m = 0
    # Validate and filter items: only consider items with non-negative price and value, and price <= n
    valid_items = []
    for item in items:
        if len(item) != 2:
            continue
        price, value = item
        if isinstance(price, int) and isinstance(value, int) and price >= 0 and value >= 0 and price <= n:
            valid_items.append((price, value))

    # If no valid items, return 0
    if not valid_items:
        return 0

    # Standard 0-1 knapsack DP
    # dp[j] = maximum importance value with budget j
    dp = [0] * (n + 1)

    for price, value in valid_items:
        # Traverse backwards to ensure each item is used at most once
        for j in range(n, price - 1, -1):
            new_val = dp[j - price] + value
            if new_val > dp[j]:
                dp[j] = new_val

    return dp[n]

