def count_partitions(n: int, k: int, x: int) -> int:
    if k <= 0:
        return 1 if n == 0 else 0
    if n < k * x:
        return 0
    if k == 1:
        return 1 if n >= x else 0
    total = 0
    for first_part in range(x, n - (k - 1) * x + 1):
        remaining_n = n - first_part
        total += count_partitions(remaining_n, k - 1, max(x, first_part))
    return total

def count_partitions(n: int, k: int, x: int) -> int:
    if k <= 0 or x < 1:
        return 0
    remaining = n - k * x
    if remaining < 0:
        return 0

    memo = {}

    def dp(n_rem, start):
        if n_rem < 0:
            return 0
        if n_rem == 0:
            return 1
        if n_rem < start:
            return 0

        if (n_rem, start) in memo:
            return memo[(n_rem, start)]

        result = 0
        for part in range(start, n_rem + 1):
            result += dp(n_rem - part, part)

        memo[(n_rem, start)] = result
        return result

    return dp(remaining, 1)

