        raise ValueError("Inorder and postorder traversals must be of the same length")

    if not inorder:
        return ""

    postorder_index = len(postorder) - 1
    inorder_map = {char: idx for idx, char in enumerate(inorder)}
    result = []

    def helper(in_left, in_right, post_left, post_right):
        if in_left > in_right or post_left > post_right:
            return

        root = postorder[post_right]
        result.append(root)

        in_root = inorder_map[root]

        # Size of left subtree
        left_size = in_root - in_left

        # Recursively build left and right subtrees
        helper(in_left, in_root - 1, post_left, post_left + left_size - 1)
        helper(in_root + 1, in_right, post_left + left_size, post_right - 1)

    helper(0, len(inorder) - 1, 0, len(postorder) - 1)
    return ''.join(result)
