def string_transformation(A: str, B: str, rules: List[Tuple[str, str]]) -> Union[int, str]:
    if A == B:
        return 0

    max_steps = 10
    visited = set([A])
    queue = deque([(A, 0)])

    while queue:
        current_string, steps = queue.popleft()
        if steps == max_steps:
            continue

        for from_sub, to_sub in rules:
            # Replace all occurrences of from_sub with to_sub
            if from_sub in current_string:
                new_string = current_string.replace(from_sub, to_sub)
                if new_string not in visited:
                    if new_string == B:
                        return steps + 1
                    visited.add(new_string)
                    queue.append((new_string, steps + 1))

    return "NO ANSWER!"
