        if not isinstance(x, int) or not isinstance(y, int) or not (0 <= x <= 9) or not (0 <= y <= 9):
            continue
        if x not in digit_map:
            digit_map[x] = set()
        digit_map[x].add(y)

    if not digit_map:
        return 1

    seen = set()
    queue = [num_str]
    seen.add(num_str)

    while queue:
        queue = queue.copy()
        new_queue = []
        for num in queue:
            if not num:
                continue
            # For each digit position, try applying all possible transformations
            for i in range(len(num)):
                current_digit = int(num[i])
                # Check if this digit has any transformation rules
                if current_digit in digit_map:
                    for new_digit in digit_map[current_digit]:
                        # Create the new number with the digit replaced
                        new_num = num[:i] + str(new_digit) + num[i+1:]
                        # Avoid leading zeros unless the number is just "0"
                        if len(new_num) > 1 and new_num[0] == '0':
                            continue
                        if new_num not in seen:
                            seen.add(new_num)
                            new_queue.append(new_num)
        queue = new_queue

    return len(seen)

def generate_numbers(n, rules):
    original = str(n)
    visited = set()
    queue = [original]
    visited.add(original)

    # Precompute the set of (digit, new_digit) rules for efficient lookup
    rule_set = set(rules)

    while queue:
        current = queue.pop(0)
        # Try to apply each rule on each digit position
        for i in range(len(current)):
            digit = current[i]
            for (d_from, d_to) in rules:
                if digit == str(d_from):
                    # Create the new number by replacing digit at position i
                    new_num = current[:i] + str(d_to) + current[i+1:]
                    # Avoid leading zeros unless the number is "0"
                    if len(new_num) > 1 and new_num[0] == '0':
                        continue
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)

    return len(visited)

