            elif "IS GUILTY" in cleaned:
                # Extract the subject: e.g., "ALICE IS GUILTY"
                parts = cleaned.split()
                if len(parts) >= 3 and parts[1] == "IS" and parts[2] == "GUILTY":
                    subject = parts[0]
                    is_true = (subject == scenario)
                else:
