                # e.g., "ALICE IS NOT GUILTY"
                parts = cleaned.split()
                if len(parts) >= 4 and parts[1] == "IS" and parts[2] == "NOT" and parts[3] == "GUILTY":
                    subject = parts[0]
                    is_true = (subject != scenario)
