def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")

    # Initialize a list to store Catalan numbers up to n
    catalan = [1] * (n + 1)
    catalan[0] = 1

    if n >= 1:
        catalan[1] = 1

    # Fill in the Catalan numbers using the dynamic programming approach
    for i in range(2, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - j - 1]

    return catalan[n]
