def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    if l <= 0:
        return 0

    merged = []
    for start, end in areas:
        if start < 1:
            start = 1
        if end > l:
            end = l
        if start > end:
            continue
        if not merged or start > merged[-1][1] + 1:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)

    total_cleared = 0
    for start, end in merged:
        total_cleared += end - start + 1

    return l - total_cleared

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    if T < 0 or M < 0:
        return 0
    if not herbs:
        return 0

    # Initialize dp array where dp[t] represents the maximum value achievable with time t
    dp = [0] * (T + 1)

    for t, value in herbs:
        if t > T:
            continue
        # Traverse backwards to avoid using the same herb multiple times
        for time in range(T, t - 1, -1):
            if dp[time - t] + value > dp[time]:
                dp[time] = dp[time - t] + value

    return dp[T]

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    if T < 0 or M < 0:
        return 0
    if M == 0:
        return 0
    # dp[j] represents the maximum value achievable with total time j
    dp = [0] * (T + 1)
    for i in range(M):
        if i >= len(herbs):
            break
        time, value = herbs[i]
        if time < 0 or value < 0:
            continue
        # Update dp in reverse order to avoid using the same item multiple times
        for j in range(T, time - 1, -1):
            new_value = dp[j - time] + value
            if new_value > dp[j]:
                dp[j] = new_value
    return dp[T]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    if V <= 0:
        return V
    if n <= 0 or not volumes:
        return V

    # dp[j] will represent the maximum volume that can be occupied with capacity j
    dp = [0] * (V + 1)

    # Iterate through each item
    for i in range(n):
        vol = volumes[i]
        # Traverse from high to low to avoid using the same item multiple times
        for j in range(V, vol - 1, -1):
            if dp[j - vol] + vol > dp[j]:
                dp[j] = dp[j - vol] + vol

    max_occupied = dp[V]
    return V - max_occupied

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    if V < 0:
        raise ValueError("Capacity V must be non-negative")
    if n < 0:
        raise ValueError("Number of items n must be non-negative")
    if len(volumes) < n:
        raise ValueError("Not enough volumes provided for the given n")

    # Handle edge case where V is 0
    if V == 0:
        return 0

    # Use DP to find the maximum capacity that can be filled exactly
    # dp[j] = True if capacity j can be filled with some subset of items
    dp = [False] * (V + 1)
    dp[0] = True

    # Process each volume, only consider the first n volumes
    for i in range(n):
        vol = volumes[i]
        if vol < 0:
            raise ValueError(f"Volume at index {i} is negative: {vol}")
        # Traverse backwards to avoid using the same item multiple times
        if vol <= V:
            for j in range(V, vol - 1, -1):
                if dp[j - vol]:
                    dp[j] = True

    # Find the largest capacity that can be filled exactly (or as close as possible)
    # Since we want minimum remaining space, we find the largest j such that dp[j] is True
    max_occupied = 0
    for j in range(V, -1, -1):
        if dp[j]:
            max_occupied = j
            break

    return V - max_occupied

