def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Edge case: if V is negative, return it as is? Or handle appropriately?
    # Since it's capacity, we assume V >= 0
    if V < 0:
        return V
    if n <= 0:
        return V

    # Standard 0/1 knapsack to find maximum volume <= V
    # dp[j] = maximum sum achievable with capacity j
    dp = [0] * (V + 1)

    for i in range(n):
        vol = volumes[i]
        if vol < 0:
            continue
        if vol > V:
            # This item cannot fit, skip
            continue
        # Traverse from V down to vol
        for j in range(V, vol - 1, -1):
            if dp[j - vol] + vol > dp[j]:
                dp[j] = dp[j - vol] + vol

    max_occupied = max(dp)
    return V - max_occupied
