def vigenere_decrypt(key: str, ciphertext: str) -> str:
    if not key:
        return ciphertext

    key = key.lower()
    plaintext = []
    key_index = 0
    key_len = len(key)

    for char in ciphertext:
        if char.isalpha():
            if char.islower():
                shift = ord(key[key_index % key_len]) - ord('a')
                shifted_char = chr((ord(char) - ord('a') - shift + 26) % 26 + ord('a'))
            else:
                shift = ord(key[key_index % key_len].upper()) - ord('A')
                shifted_char = chr((ord(char) - ord('A') - shift + 26) % 26 + ord('A'))
            plaintext.append(shifted_char)
            key_index += 1
        else:
            plaintext.append(char)

    return ''.join(plaintext)
