    inc = [1] * n
    for i in range(1, n):
        for j in range(i):
            if heights[j] < heights[i]:
                inc[i] = max(inc[i], inc[j] + 1)

    # Compute longest decreasing subsequence from right (including current)
    dec = [1] * n
    for i in range(n - 2, -1, -1):
        for j in range(n - 1, i, -1):
            if heights[j] < heights[i]:
                dec[i] = max(dec[i], dec[j] + 1)

    # Find the maximum size of choir formation: max over i of (inc[i] + dec[i] - 1)
    max_choir_size = 0
    for i in range(n):
        choir_size = inc[i] + dec[i] - 1
        if choir_size > max_choir_size:
            max_choir_size = choir_size

    return n - max_choir_size

def minimum_students_to_leave(heights):
    if not heights:
        return 0
    n = len(heights)

    # If there's only one student, no one needs to leave
    if n == 1:
        return 0

    # Calculate the Longest Increasing Subsequence from the left (up to and including i)
    # inc_left[i] = length of LIS ending at index i
    inc_left = [1] * n
    for i in range(1, n):
        for j in range(i):
            if heights[j] < heights[i]:
                if inc_left[j] + 1 > inc_left[i]:
                    inc_left[i] = inc_left[j] + 1

    # Calculate the Longest Decreasing Subsequence from the right (starting from i)
    # dec_right[i] = length of LDS starting at index i
    # We can think of it as: longest increasing subsequence in the reversed list starting at the mirror position
    # Alternatively, for each i, dec_right[i] is the length of the longest decreasing subsequence that starts at index i.
    # We compute it by scanning from right to left, looking for elements smaller than current.
    dec_right = [1] * n
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i]:
                if dec_right[j] + 1 > dec_right[i]:
                    dec_right[i] = dec_right[j] + 1

    # Now, for each possible peak position i, the choir formation length is:
    # inc_left[i] + dec_right[i] - 1  (because the height at i is counted in both)
    # But wait: the formation must be strictly increasing then strictly decreasing.
    # The above approach using LIS (strictly increasing) and LDS (strictly decreasing) works.

    max_length = 0
    for i in range(n):
        # The total length of the formation if i is the peak
        formation_length = inc_left[i] + dec_right[i] - 1
        if formation_length > max_length:
            max_length = formation_length

    return n - max_length

def minimum_students_to_leave(heights):
    if not heights:
        return 0
    n = len(heights)
    # Calculate Longest Increasing Subsequence (LIS) ending at each index
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if heights[j] < heights[i]:
                lis[i] = max(lis[i], lis[j] + 1)
    # Calculate Longest Decreasing Subsequence (LDS) starting at each index
    lds = [1] * n
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i]:
                lds[i] = max(lds[i], lds[j] + 1)
    # Find the maximum possible choir formation size (LIS + LDS - 1)
    max_choir_size = max(lis[i] + lds[i] - 1 for i in range(n))
    # Minimum students to leave is total students minus maximum choir size
    return n - max_choir_size

def sort_students(student_scores):
    if not isinstance(student_scores, list):
        raise ValueError("Input must be a list")

    for i, student in enumerate(student_scores):
        if not isinstance(student, (tuple, list)) or len(student) != 3:
            raise ValueError(f"Each student must be a tuple/list of 3 elements at index {i}")
        student_num, total_score, chinese_score = student
        if not isinstance(student_num, int):
