def min_groups(w, n, prices):
    if n == 0:
        return 0
    prices_sorted = sorted(prices[:n])
    left = 0
    right = n - 1
    groups = 0
    while left <= right:
        if prices_sorted[left] + (prices_sorted[right] if left != right else 0) <= w:
            left += 1
        right -= 1
        groups += 1
    return groups

def min_groups(w, n, prices):
    if n <= 0:
        return 0
    if not prices or len(prices) != n:
        raise ValueError("prices list must have exactly n elements")
    prices_sorted = sorted(prices)
    left = 0
    right = n - 1
    groups = 0
    while left <= right:
        if left == right:
            groups += 1
            break
        if prices_sorted[left] + prices_sorted[right] <= w:
            left += 1
        right -= 1
        groups += 1
    return groups

def min_groups(w, n, prices):
    if n == 0:
        return 0
    if len(prices) < n:
        prices = prices + [0] * (n - len(prices))
    prices = prices[:n]
    prices.sort()
    left = 0
    right = n - 1
    groups = 0
    while left <= right:
        if left == right:
            groups += 1
            break
        if prices[left] + prices[right] <= w:
            left += 1
            right -= 1
        else:
            right -= 1
        groups += 1
    return groups

def hanoi_double_iterative(n: int) -> int:
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")

    if n == 0:
        return 0
    total = 0
    current = 0
    for k in range(1, n + 1):
        current = 2 * current + 2
        total = current
    return total

def hanoi_double_iterative(n: int) -> int:
    if n < 0:
        return 0
    moves = 2
    for _ in range(1, n):
        moves = 2 * moves + 2
    return moves

def hanoi_double_iterative(n: int) -> int:
    if not isinstance(n, int) or n < 1:
        raise ValueError("n must be a positive integer")
    if n == 1:
        return 2
    moves = 2
    for i in range(2, n + 1):
        moves = 4 * moves - 2
    return moves

def hanoi_double_iterative(n: int) -> int:
    if n < 0 or not isinstance(n, int):
        raise ValueError("n must be a non-negative integer")
    if n == 0:
        return 0
    moves = 2
    for i in range(1, n):
        moves = 2 * moves + 2
    return moves

def total_smoked_cigarettes(n, k):
    if n <= 0:
        return 0
    if k <= 1:
        return n if k == 1 else 0
    total = n
    butts = n
    while butts >= k:
        new_cig = butts // k
        total += new_cig
        butts = new_cig + (butts % k)
    return total

def total_smoked_cigarettes(n, k):
    if n <= 0:
        return 0
    if k <= 1:
        return float('inf')
    total = n
    butts = n
    while butts >= k:
        new_cigarettes = butts // k
        total += new_cigarettes
        butts = butts % k + new_cigarettes
    return total
